import type {
  AuroraFlowPalette,
  AuroraFlowPreset,
  AuroraFlowRgb,
} from './types';

export const AURORA_FLOW_PRESETS: Record<AuroraFlowPreset, AuroraFlowPalette> =
  {
    ocean: ['#020817', '#062a55', '#0b62b4', '#39bfe6', '#d9f6ff'],
    aurora: ['#07051a', '#25105e', '#4d43c7', '#20a7a0', '#c3f5eb'],
    sky: ['#071425', '#16456e', '#4d9acb', '#9edbf0', '#eefaff'],
    cloud: ['#20242c', '#4b5360', '#8c98a7', '#ced5dc', '#f7f8fa'],
    sunset: ['#1d0812', '#6d1e3e', '#d95b48', '#f2a35b', '#ffe2a6'],
    midnight: ['#010206', '#080d1c', '#17264d', '#304d7f', '#a8c6ef'],
    ice: ['#07141b', '#123b49', '#3e8796', '#a6e4e7', '#f1ffff'],
    dream: ['#10091c', '#3b1d58', '#8d4ca0', '#df91bd', '#ffe7f1'],
    nebula: ['#090512', '#32104a', '#813b8f', '#315fa8', '#e2b7ff'],
    emerald: ['#03120e', '#073c2c', '#0e7358', '#53c89f', '#d9fff0'],
    lavender: ['#100b20', '#30205d', '#6252a6', '#b58bc6', '#f4dff4'],
    mono: ['#020202', '#171717', '#414141', '#8a8a8a', '#f2f2f2'],
  };

export const AURORA_FLOW_PRESET_NAMES: readonly AuroraFlowPreset[] = [
  'ocean',
  'aurora',
  'sky',
  'cloud',
  'sunset',
  'midnight',
  'ice',
  'dream',
  'nebula',
  'emerald',
  'lavender',
  'mono',
];

const HEX_COLOR_REGEX = /^#?[\da-f]{6}$/i;

export function clamp(value: number, minimum: number, maximum: number): number {
  return Math.min(maximum, Math.max(minimum, value));
}

export function sanitizeHexColor(
  value: string | undefined,
  fallback: string,
): string {
  const trimmed = value?.trim() ?? '';
  if (!HEX_COLOR_REGEX.test(trimmed)) return fallback;
  return trimmed.startsWith('#') ? trimmed : `#${trimmed}`;
}

export function hexToRgb01(hex: string): AuroraFlowRgb {
  const normalized = hex.slice(1);
  return [
    Number.parseInt(normalized.slice(0, 2), 16) / 255,
    Number.parseInt(normalized.slice(2, 4), 16) / 255,
    Number.parseInt(normalized.slice(4, 6), 16) / 255,
  ];
}

import {
  AURORA_FLOW_FRAGMENT_SHADER,
  AURORA_FLOW_VERTEX_SHADER,
} from './aurora-flow-shader';
import type { AuroraFlowRenderer } from './types';

const UNIFORM_NAMES = [
  'u_res',
  'u_pointer',
  'u_flowDirection',
  'u_time',
  'u_speed',
  'u_animationSpeed',
  'u_intensity',
  'u_opacity',
  'u_blur',
  'u_contrast',
  'u_brightness',
  'u_layers',
  'u_flowScale',
  'u_flowStrength',
  'u_pointerStrength',
  'u_scroll',
  'u_parallaxStrength',
  'u_grainOpacity',
  'u_noiseOpacity',
  'u_noiseScale',
  'u_lighting',
  'u_lightingIntensity',
  'u_lightingRadius',
  'u_lightingSpeed',
  'u_ambientGlow',
  'u_ambientOpacity',
  'u_vignette',
  'u_color0',
  'u_color1',
  'u_color2',
  'u_color3',
  'u_color4',
] as const;

type UniformName = (typeof UNIFORM_NAMES)[number];

const COLOR_UNIFORMS: readonly UniformName[] = [
  'u_color0',
  'u_color1',
  'u_color2',
  'u_color3',
  'u_color4',
];

function compileShader(
  gl: WebGLRenderingContext,
  type: number,
  source: string,
): WebGLShader | null {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

export function createAuroraFlowRenderer(
  canvas: HTMLCanvasElement,
): AuroraFlowRenderer | null {
  const gl = canvas.getContext('webgl', {
    antialias: false,
    alpha: true,
    premultipliedAlpha: true,
    powerPreference: 'high-performance',
  });
  if (!gl) return null;

  const vertexShader = compileShader(
    gl,
    gl.VERTEX_SHADER,
    AURORA_FLOW_VERTEX_SHADER,
  );
  const fragmentShader = compileShader(
    gl,
    gl.FRAGMENT_SHADER,
    AURORA_FLOW_FRAGMENT_SHADER,
  );
  const program = gl.createProgram();
  const buffer = gl.createBuffer();

  const release = () => {
    if (buffer) gl.deleteBuffer(buffer);
    if (program) gl.deleteProgram(program);
    if (vertexShader) gl.deleteShader(vertexShader);
    if (fragmentShader) gl.deleteShader(fragmentShader);
    gl.getExtension('WEBGL_lose_context')?.loseContext();
  };

  if (!vertexShader || !fragmentShader || !program || !buffer) {
    release();
    return null;
  }

  gl.attachShader(program, vertexShader);
  gl.attachShader(program, fragmentShader);
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    release();
    return null;
  }

  gl.useProgram(program);
  const position = gl.getAttribLocation(program, 'position');
  if (position < 0) {
    release();
    return null;
  }

  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]),
    gl.STATIC_DRAW,
  );
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

  const uniforms = new Map<UniformName, WebGLUniformLocation>();
  for (const name of UNIFORM_NAMES) {
    const location = gl.getUniformLocation(program, name);
    if (!location) {
      release();
      return null;
    }
    uniforms.set(name, location);
  }

  const set1 = (name: UniformName, value: number) => {
    gl.uniform1f(uniforms.get(name) ?? null, value);
  };
  const set2 = (name: UniformName, x: number, y: number) => {
    gl.uniform2f(uniforms.get(name) ?? null, x, y);
  };

  return {
    resize(width, height) {
      canvas.width = width;
      canvas.height = height;
      gl.viewport(0, 0, width, height);
      set2('u_res', width, height);
    },
    draw(frame) {
      const s = frame.settings;
      const radians = (s.flowDirection * Math.PI) / 180;
      set2('u_pointer', frame.pointerX, frame.pointerY);
      set2('u_flowDirection', Math.cos(radians), Math.sin(radians));
      set1('u_time', frame.time);
      set1('u_speed', s.speed);
      set1('u_animationSpeed', s.animationSpeed);
      set1('u_intensity', s.intensity);
      set1('u_opacity', s.opacity);
      set1('u_blur', s.blur);
      set1('u_contrast', s.contrast);
      set1('u_brightness', s.brightness);
      set1('u_layers', s.layers);
      set1('u_flowScale', s.flowScale);
      set1('u_flowStrength', s.flowStrength);
      set1('u_pointerStrength', frame.pointerStrength);
      set1('u_scroll', frame.scroll);
      set1('u_parallaxStrength', s.parallaxStrength);
      set1('u_grainOpacity', s.grainOpacity);
      set1('u_noiseOpacity', s.noiseOpacity);
      set1('u_noiseScale', s.noiseScale);
      set1('u_lighting', s.lighting);
      set1('u_lightingIntensity', s.lightingIntensity);
      set1('u_lightingRadius', s.lightingRadius);
      set1('u_lightingSpeed', s.lightingSpeed);
      set1('u_ambientGlow', s.ambientGlow);
      set1('u_ambientOpacity', s.ambientOpacity);
      set1('u_vignette', s.vignette);
      s.palette.forEach((color, index) => {
        const name = COLOR_UNIFORMS[index];
        if (!name) return;
        gl.uniform3f(uniforms.get(name) ?? null, color[0], color[1], color[2]);
      });
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    },
    dispose: release,
  };
}

export const AURORA_FLOW_VERTEX_SHADER = `
attribute vec2 position;

void main() {
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

export const AURORA_FLOW_FRAGMENT_SHADER = `
precision highp float;

uniform vec2 u_res;
uniform vec2 u_pointer;
uniform vec2 u_flowDirection;
uniform float u_time;
uniform float u_speed;
uniform float u_animationSpeed;
uniform float u_intensity;
uniform float u_opacity;
uniform float u_blur;
uniform float u_contrast;
uniform float u_brightness;
uniform float u_layers;
uniform float u_flowScale;
uniform float u_flowStrength;
uniform float u_pointerStrength;
uniform float u_scroll;
uniform float u_parallaxStrength;
uniform float u_grainOpacity;
uniform float u_noiseOpacity;
uniform float u_noiseScale;
uniform float u_lighting;
uniform float u_lightingIntensity;
uniform float u_lightingRadius;
uniform float u_lightingSpeed;
uniform float u_ambientGlow;
uniform float u_ambientOpacity;
uniform float u_vignette;
uniform vec3 u_color0;
uniform vec3 u_color1;
uniform vec3 u_color2;
uniform vec3 u_color3;
uniform vec3 u_color4;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float valueNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);

  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));

  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

mat2 rotate2d(float angle) {
  float s = sin(angle);
  float c = cos(angle);
  return mat2(c, -s, s, c);
}

float fbm(vec2 p) {
  float value = 0.0;
  float amplitude = 0.52;
  mat2 turn = mat2(0.84, 0.54, -0.54, 0.84);

  for (int i = 0; i < 7; i++) {
    float enabled = step(float(i) + 0.5, u_layers);
    value += amplitude * valueNoise(p) * enabled;
    p = turn * p * 2.03 + 0.17;
    amplitude *= 0.5;
  }

  return value;
}

vec3 grade(vec3 color, float contrast, float brightness) {
  color = (color - 0.5) * contrast + 0.5;
  return color * brightness;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float aspect = u_res.x / max(u_res.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);

  float t = u_time * 0.075 * u_speed * u_animationSpeed;
  vec2 direction = normalize(u_flowDirection + vec2(0.0001));
  vec2 crossDirection = vec2(-direction.y, direction.x);

  vec2 pointer = (u_pointer - 0.5) * vec2(aspect, 1.0);
  vec2 pointerDelta = pointer - p;
  float pointerFalloff = smoothstep(0.68, 0.0, length(pointerDelta));
  p += crossDirection * pointerDelta.x * pointerFalloff * 0.035 * u_pointerStrength;
  p += direction * pointerDelta.y * pointerFalloff * 0.022 * u_pointerStrength;

  p.y += u_scroll * 0.045 * u_parallaxStrength;
  p.x -= u_scroll * 0.018 * u_parallaxStrength;

  float scale = max(0.2, u_flowScale);
  vec2 broadP = p * scale;
  float warpA = fbm(broadP * 0.82 + direction * t * 0.71 + vec2(2.7, -1.3));
  float warpB = fbm(rotate2d(0.73) * broadP * 1.08 - crossDirection * t * 0.53 + vec2(-4.1, 3.6));
  float warpC = fbm(rotate2d(-0.46) * broadP * 1.42 + vec2(-t * 0.31, t * 0.43) + 8.2);

  vec2 silk = broadP;
  silk += vec2(warpA - 0.5, warpB - 0.5) * 0.72 * u_flowStrength;
  silk += direction * (warpC - 0.5) * 0.28 * u_flowStrength;

  float fieldA = fbm(rotate2d(0.28) * silk * 0.74 + direction * t * 0.83 + 1.9);
  float fieldB = fbm(rotate2d(-0.81) * silk * 0.91 - crossDirection * t * 0.61 + 5.4);
  float fieldC = fbm(rotate2d(1.17) * silk * 1.16 + vec2(t * 0.37, -t * 0.29) + 9.7);

  float softness = clamp(u_blur * 0.08, 0.025, 0.2);
  float veilA = smoothstep(0.28 - softness, 0.76 + softness, fieldA + (warpB - 0.5) * 0.28);
  float veilB = smoothstep(0.34 - softness, 0.82 + softness, fieldB + (warpC - 0.5) * 0.24);
  float veilC = smoothstep(0.42 - softness, 0.86 + softness, fieldC + (fieldA - 0.5) * 0.18);

  float folded = 0.5 + 0.5 * sin(
    silk.y * 2.7 + silk.x * 0.72 + warpA * 3.1 - warpB * 1.9 + t * 0.47
  );
  float silkFold = smoothstep(0.18, 0.92, folded) * smoothstep(0.12, 0.94, fieldB);

  vec3 color = mix(u_color0, u_color1, clamp(0.22 + veilA * 0.62, 0.0, 1.0));
  color = mix(color, u_color2, veilB * 0.58 * u_intensity);
  color = mix(color, u_color3, veilC * 0.42 * u_intensity);
  color += u_color4 * silkFold * 0.13 * u_intensity;

  vec2 lightCenter = vec2(
    0.5 + sin(t * 0.37 * u_lightingSpeed + 1.4) * 0.24,
    0.48 + cos(t * 0.29 * u_lightingSpeed - 0.8) * 0.18
  );
  vec2 lightDelta = uv - lightCenter;
  lightDelta = rotate2d(0.42 + warpA * 0.22) * lightDelta;
  lightDelta *= vec2(0.74, 1.32);
  float lightRadius = max(0.08, u_lightingRadius * 0.34);
  float bloom = exp(-dot(lightDelta, lightDelta) / (lightRadius * lightRadius));
  bloom *= 0.76 + fieldC * 0.24;
  color += mix(u_color3, u_color4, 0.58) * bloom * 0.22 * u_lightingIntensity * u_lighting;

  vec2 ambientDelta = uv - vec2(0.52, 0.47);
  ambientDelta *= vec2(0.72, 1.0);
  float ambient = exp(-dot(ambientDelta, ambientDelta) / 0.34);
  color += mix(u_color2, u_color4, 0.5) * ambient * 0.12 * u_ambientOpacity * u_ambientGlow;

  float haze = fbm(p * max(0.5, u_noiseScale) * 2.6 + vec2(-t * 0.18, t * 0.14));
  color += (haze - 0.5) * u_noiseOpacity * 0.16;

  float vignetteMask = smoothstep(0.18, 1.08, length((uv - 0.5) * vec2(1.0, 0.86)));
  color *= 1.0 - vignetteMask * 0.52 * u_vignette;

  float grain = hash(gl_FragCoord.xy + floor(u_time * 12.0) * 17.0) - 0.5;
  color += grain * u_grainOpacity * 0.16;
  color = grade(color, u_contrast, u_brightness);

  gl_FragColor = vec4(clamp(color, 0.0, 1.0), clamp(u_opacity, 0.0, 1.0));
}
`;

export { default as AuroraFlow } from './AuroraFlow.vue';
export {
  AURORA_FLOW_PRESETS,
  AURORA_FLOW_PRESET_NAMES,
} from './aurora-flow-presets';
export type {
  AuroraFlowPalette,
  AuroraFlowPreset,
  AuroraFlowProps,
} from './types';

export type AuroraFlowPreset =
  | 'ocean'
  | 'aurora'
  | 'sky'
  | 'cloud'
  | 'sunset'
  | 'midnight'
  | 'ice'
  | 'dream'
  | 'nebula'
  | 'emerald'
  | 'lavender'
  | 'mono';

export type AuroraFlowPalette = readonly [
  string,
  string,
  string,
  string,
  string,
];

export type AuroraFlowRgb = [number, number, number];

export interface AuroraFlowSettings {
  palette: AuroraFlowRgb[];
  speed: number;
  intensity: number;
  opacity: number;
  blur: number;
  contrast: number;
  brightness: number;
  grainOpacity: number;
  layers: number;
  flowScale: number;
  flowStrength: number;
  flowDirection: number;
  animationSpeed: number;
  pointerStrength: number;
  scrollInteraction: boolean;
  parallaxStrength: number;
  lighting: number;
  lightingIntensity: number;
  lightingRadius: number;
  lightingSpeed: number;
  ambientGlow: number;
  ambientOpacity: number;
  noiseOpacity: number;
  noiseScale: number;
  vignette: number;
  pointerInteraction: boolean;
}

export interface AuroraFlowProps {
  /** Up to five custom hex colors overriding the selected preset. */
  colors?: readonly string[];
  preset?: AuroraFlowPreset;
  speed?: number;
  intensity?: number;
  opacity?: number;
  blur?: number;
  contrast?: number;
  brightness?: number;
  grain?: boolean;
  grainOpacity?: number;
  layers?: number;
  flowScale?: number;
  flowStrength?: number;
  flowDirection?: number;
  animationSpeed?: number;
  pointerInteraction?: boolean;
  pointerStrength?: number;
  scrollInteraction?: boolean;
  parallaxStrength?: number;
  lighting?: boolean;
  lightingIntensity?: number;
  lightingRadius?: number;
  lightingSpeed?: number;
  ambientGlow?: boolean;
  ambientOpacity?: number;
  noise?: boolean;
  noiseOpacity?: number;
  noiseScale?: number;
  vignette?: boolean;
  vignetteStrength?: number;
  /** CSS border-radius; numbers are treated as px. */
  borderRadius?: string | number;
  class?: string;
}

export interface AuroraFlowFrame {
  settings: AuroraFlowSettings;
  time: number;
  pointerX: number;
  pointerY: number;
  pointerStrength: number;
  scroll: number;
}

export interface AuroraFlowRenderer {
  resize: (width: number, height: number) => void;
  draw: (frame: AuroraFlowFrame) => void;
  dispose: () => void;
}
